{"summary": "Print Value and Volume headers and 2023 data row values", "command": "python3 - <<'PY'
import openpyxl
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)
for sheet in ['Value','Volume']:
    ws=wb[sheet]
    print('\n==',sheet,'==')
    headers={}
    for c in range(1,ws.max_column+1):
        v=ws.cell(1,c).value
        if v not in (None,''):
            headers[c]=v
    # find row where colA == '2023'
    year_row=None
    for r in range(1,ws.max_row+1):
        if str(ws.cell(r,1).value).strip()== '2023':
            year_row=r
            break
    print('year_row',year_row)
    for c,v in headers.items():
        if c<=2: continue
        val=ws.cell(year_row,c).value if year_row else None
        if val not in (None,''):
            print(get_column_letter(c),v,'->',val)
PY"}

